import { MindStudioError } from './errors.js';
import type { RateLimiter } from './rate-limit.js';

export interface HttpClientConfig {
  baseUrl: string;
  token: string;
  rateLimiter: RateLimiter;
  maxRetries: number;
}

export async function request<T>(
  config: HttpClientConfig,
  method: 'GET' | 'POST',
  path: string,
  body?: unknown,
): Promise<{ data: T; headers: Headers }> {
  const url = `${config.baseUrl}/developer/v2${path}`;

  await config.rateLimiter.acquire();

  try {
    return await requestWithRetry<T>(config, method, url, body, 0);
  } finally {
    config.rateLimiter.release();
  }
}

async function requestWithRetry<T>(
  config: HttpClientConfig,
  method: string,
  url: string,
  body: unknown,
  attempt: number,
): Promise<{ data: T; headers: Headers }> {
  const res = await fetch(url, {
    method,
    headers: {
      Authorization: `Bearer ${config.token}`,
      'Content-Type': 'application/json',
      'User-Agent': '@mindstudio-ai/agent',
    },
    body: body != null ? JSON.stringify(body) : undefined,
  });

  // Update rate limiter with latest server-reported limits
  config.rateLimiter.updateFromHeaders(res.headers);

  // Retry on rate limits and transient server errors (502, 503, 504)
  // Retry on rate limits and transient server errors (502, 503, 504)
  if (attempt < config.maxRetries && (res.status === 429 || res.status === 502 || res.status === 503 || res.status === 504)) {
    const retryAfter = res.headers.get('retry-after');
    const waitMs = retryAfter
      ? parseFloat(retryAfter) * 1000
      : Math.min(1000 * Math.pow(2, attempt), 10000); // 1s, 2s, 4s, 8s, 10s cap
    await sleep(waitMs);
    return requestWithRetry<T>(config, method, url, body, attempt + 1);
  }

  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`;
    let code = 'api_error';
    let details: unknown;

    try {
      const text = await res.text();
      try {
        const body = JSON.parse(text) as Record<string, unknown>;
        details = body;
        const errMsg =
          (typeof body.errorMessage === 'string' ? body.errorMessage : undefined) ??
          (typeof body.errorString === 'string' ? body.errorString : undefined) ??
          (typeof body.error === 'string' ? body.error : undefined) ??
          (typeof body.message === 'string' ? body.message : undefined) ??
          (typeof body.details === 'string' ? body.details : undefined);
        if (errMsg) message = errMsg;
        else if (body.error || body.message || body.details) {
          message = JSON.stringify(body.error ?? body.message ?? body.details);
        }
        if (body.code) code = String(body.code);
        else if (typeof body.errorString === 'string') code = body.errorString;
      } catch {
        if (text) {
          // Strip HTML tags and collapse whitespace for readable error text
          const stripped = text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
          if (stripped) message = stripped.slice(0, 200);
        }
      }
    } catch {
      // Couldn't read response body
    }

    throw new MindStudioError(message, code, res.status, details);
  }

  const data = (await res.json()) as T;
  return { data, headers: res.headers };
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
